Value.Calculation:
Let ( d = Get ( CurrentDate ) ;
	Year ( d ) & "-" & Right ( "0" & Month ( d ) ; 2 ) & "-" & Right ( "0" & Day ( d ) ; 2 )
)

Let ( [
	pm = $periodMode ;
	monOffset = Mod ( DayOfWeek ( $anchor ) - 2 ; 7 )
] ;
	Case (
		pm = "week"  ; $anchor - monOffset ;
		pm = "month" ; Date ( Month ( $anchor ) ; 1 ; Year ( $anchor ) ) ;
		$anchor
	)
)

Let ( [
	pm = $periodMode ;
	monOffset = Mod ( DayOfWeek ( $anchor ) - 2 ; 7 )
] ;
	Case (
		pm = "week"  ; $anchor - monOffset + 6 ;
		pm = "month" ; Date ( Month ( $anchor ) + 1 ; 0 ; Year ( $anchor ) ) ;
		$anchor
	)
)

Let ( [
	months = List ( "Januar" ; "Februar" ; "Mart" ; "April" ; "Maj" ; "Juni" ; "Juli" ; "Avgust" ; "Septembar" ; "Oktobar" ; "Novembar" ; "Decembar" ) ;
	mFrom   = GetValue ( months ; Month ( $fromD ) ) ;
	mTo     = GetValue ( months ; Month ( $toD ) ) ;
	mAnchor = GetValue ( months ; Month ( $anchor ) )
] ;
	Case (
		$periodMode = "week" ;
			If ( Month ( $fromD ) = Month ( $toD ) ;
				"Sedmica: " & Day ( $fromD ) & "–" & Day ( $toD ) & ". " & mTo & " " & Year ( $toD ) ;
				"Sedmica: " & Day ( $fromD ) & ". " & mFrom & " – " & Day ( $toD ) & ". " & mTo & " " & Year ( $toD )
			) ;
		$periodMode = "month" ;
			mAnchor & " " & Year ( $anchor ) ;
		Day ( $anchor ) & ". " & mAnchor & " " & Year ( $anchor )
	)
)

JSONSetElement ( "{}" ;
	[ "periodMode" ; $periodMode ; JSONString ] ;
	[ "anchorDate" ; $anchorStr  ; JSONString ] ;
	[ "statuses"   ; $statuses   ; JSONArray  ] ;
	[ "offset"     ; $offset     ; JSONNumber ] ;
	[ "limit"      ; $limit      ; JSONNumber ]
)

JSONSetElement ( "[]" ;
	[ 0 ; "id"          ; JSONString ] ;
	[ 1 ; "number"      ; JSONString ] ;
	[ 2 ; "status"      ; JSONString ] ;
	[ 3 ; "clientName"  ; JSONString ] ;
	[ 4 ; "vehicle"     ; JSONString ] ;
	[ 5 ; "description" ; JSONString ] ;
	[ 6 ; "date"        ; JSONString ] ;
	[ 7 ; "timeStart"   ; JSONString ] ;
	[ 8 ; "timeEnd"     ; JSONString ]
)

JSONSetElement ( "[]" ;
	[ 0 ; "text" ; JSONString ] ;
	[ 1 ; "text" ; JSONString ] ;
	[ 2 ; "text" ; JSONString ] ;
	[ 3 ; "text" ; JSONString ] ;
	[ 4 ; "text" ; JSONString ] ;
	[ 5 ; "text" ; JSONString ] ;
	[ 6 ; "text" ; JSONString ] ;
	[ 7 ; "text" ; JSONString ] ;
	[ 8 ; "text" ; JSONString ]
)

JSONSetElement ( "{}" ;
	[ "periodMode" ; $periodMode ; JSONString ] ;
	[ "anchorDate" ; $anchorStr  ; JSONString ] ;
	[ "from"       ; $fromISO    ; JSONString ] ;
	[ "to"         ; $toISO      ; JSONString ] ;
	[ "label"      ; $label      ; JSONString ] ;
	[ "statuses"   ; $statuses   ; JSONArray  ] ;
	[ "page" ; JSONSetElement ( "{}" ;
		[ "offset"  ; $offset ; JSONNumber  ] ;
		[ "limit"   ; $limit  ; JSONNumber  ] ;
		[ "total"   ; $total  ; JSONNumber  ] ;
		[ "hasMore" ; $offset + $limit < $total ; JSONBoolean ]
	) ; JSONObject ]
)

JSONSetElement ( "{}" ;
	[ "orders" ; $orders ; JSONArray  ] ;
	[ "meta"   ; $meta   ; JSONObject ]
)
